"posologiaUsual": "Enxaqueca e dor neuropática: iniciar 10-25 mg à noite e aumentar 10-25 mg a cada 1-2 semanas; dose usual 25-75 mg/dia em tomada única noturna (SBCe 2022: 10-150 mg/dia).",
"doseMaxDia": "150 mg/dia em ambulatório (SBCe 2022 e bula).",
"portaria344": "C1",
"receituario": "controle_especial",
"limiteQuantidade": "Receita de Controle Especial em 2 vias (lista C1). Validade de 30 dias a partir da emissão (Art. 52, par. 1º). Quantidade máxima de 60 dias de tratamento por receita (Art. 59) e no máximo 3 substâncias da lista C1 por receita (Art. 57); acima disso, exige justificativa com CID ou diagnóstico e posologia, datada e assinada (Art. 60). Vale em todo o território nacional. Pode ser emitida eletronicamente com assinatura qualificada ICP-Brasil (RDC 1.000/2025); integração ao SNCR em implantação a partir de 30/09/2026.",
