"posologiaUsual": "Uso ambulatorial: 1,5 a 3 mg até três vezes ao dia. Casos graves, em geral hospitalares: 6 a 12 mg duas ou três vezes ao dia. Iniciar com doses baixas; idosos com doses menores.",
"doseMaxDia": "36 mg/dia em adultos (bula Lexotan); no ambulatório raramente se justifica passar de 9 mg/dia",
