"limiteQuantidade": "Notificação de Receita B (azul) acompanhada de receita: quantidade para no máximo 60 dias de tratamento (Portaria 344/98, art. 46); acima disso, justificativa com CID (art. 46, par. 1o). Validade de 30 dias, em todo o território nacional (art. 45, redação da RDC 873/2024).",
"efeitosComuns": [
"Sonolência e cansaço",
"Tontura e falta de coordenação",
"Fraqueza muscular",
"Dificuldade de memória e concentração",
"Lentidão de reflexos",
"Confusão, sobretudo em idosos"
],
"sinaisAlerta": [
"Sonolência tão forte que você não consegue acordar direito, respiração lenta ou fraca, lábios arroxeados: emergência, especialmente se tiver misturado com álcool, opioides (morfina, codeína, tramadol) ou outros calmantes.",
"Confusão, desorientação, quedas ou perda de equilíbrio, sobretudo em idosos.",
"Reações paradoxais: agitação, agressividade, alucinações ou comportamento estranho.",
"Episódios de fazer coisas dormindo (dirigir, comer, sair) sem lembrar depois.",
"Pensamentos de se machucar ou piora importante do humor.",
"Vontade de tomar mais do que o prescrito ou de buscar o remédio por outros meios."
],
"monitorizacao": [
"Reavaliar a cada renovação a indicação, a dose e a duração (a bula recomenda que o tratamento não ultrapasse 8 a 12 semanas, incluindo a retirada). Em idosos, avaliar quedas e cognição"
],
"interacoes": [
"Álcool, opioides (morfina, codeína, tramadol, oxicodona",
"FDA Boxed Warning de 2016 para depressão respiratória e morte), outros benzodiazepínicos, zolpidem, antipsicóticos sedativos, anti-histamínicos sedativos, gabapentina e pregabalina (somam sedação). Inibidores de CYP3A4 (cetoconazol, itraconazol, claritromicina), fluvoxamina e cimetidina podem aumentar o nível"
],
"gestacao": "Avise o médico se engravidar ou planejar engravidar. Uso no fim da gestação pode deixar o bebê sonolento, com o corpo mole, dificuldade para mamar e sintomas de abstinência após o nascimento. Não interrompa sozinha: a retirada precisa ser gradual. O remédio passa para o leite materno e pode deixar o bebê sonolento.",
"suspensao": "Não pare de repente, mesmo que se sinta bem. Após semanas de uso o corpo se acostuma, e a parada brusca pode causar ansiedade rebote, insônia, tremores, suor, confusão e até convulsões. A retirada deve ser feita aos poucos com o médico; a diretriz conjunta de 2025 sugere começar reduzindo cerca de 5 a 10% da dose a cada 2 a 4 semanas, ajustando conforme os sintomas.",
"orientacoes": [
"Não dirija nem opere máquinas até saber como o remédio age em você, e nunca após beber álcool.",
"Use a menor dose pelo menor tempo; este remédio não deve ser a única forma de tratar ansiedade ou insônia a longo prazo.",
"Guarde longe de crianças e não compartilhe com ninguém."
],
"alertasMedico": [
"FDA 2020: Boxed Warning de abuso, adição, dependência e abstinência para a classe. AGS Beers 2023: evitar benzodiazepínicos em idosos (declínio cognitivo, delirium, quedas, fraturas, acidentes de trânsito). Evitar associação com opioides e outros depressores do SNC. Reavaliar a necessidade a cada renovação",
"Na telerrenovação crônica, registrar indicação, tempo de uso e plano de desmame. Notificação B (azul) e documento físico até a liberação da emissão eletrônica pelo SNCR (prevista pela ANVISA para 30/09/2026, com assinatura qualificada ICP-Brasil e sistema integrado ao SNCR",
"RDC 1.000/2025). Bromazepam: bula limita a duração a 8-12 semanas incluindo a retirada",
"Uso crônico prolongado e comum no Brasil e deve motivar plano de desmame"
],
