"Bula profissional Bromazepam, ANVISA (cópia Consulta Remédios, lida em 24/09/2026). https://uploads.consultaremedios.com.br/drug_leaflet/pro/Bula-Bromazepam-Profissional-Consulta-Remedios.pdf",
