"portaria344": "Lista C1 (outras substâncias sujeitas a controle especial), Portaria SVS/MS 344/1998, conferido no Anexo I atualizado pela RDC 1.036/2026",
"receituario": "controle_especial",
"limiteQuantidade": "Receita de Controle Especial em 2 vias: quantidade para no máximo 60 dias de tratamento (Portaria 344/98, art. 59); acima disso o prescritor precisa justificar com CID ou diagnóstico (art. 60). Validade de 30 dias a partir da emissão (art. 52, par. 1o). No máximo 3 substâncias da lista C1 por receita (art. 57).",
"efeitosComuns": [
"Tremor fino nas mãos",
"Sede e vontade de urinar com mais frequência",
"Enjoo ou diarreia leve, principalmente no início",
"Aumento de peso",
"Gosto metálico na boca",
"Acne ou piora da psoríase"
],
"sinaisAlerta": [
"Sinais de intoxicação por lítio: diarreia ou vômitos persistentes, tremor forte, fraqueza, tontura, fala enrolada, andar desequilibrado, visão turva, confusão ou sonolência intensa. Pare a próxima dose e procure emergência para dosar o lítio.",
"Qualquer situação de desidratação (febre alta, diarreia, vômitos, calor intenso, dieta muito restrita) aumenta o risco de intoxicação: procure o médico.",
"Convulsão, desmaio ou coração muito lento: emergência.",
"Urinar muito mais do que o habitual com sede intensa e constante.",
"Pensamentos de se machucar ou piora importante do humor, ou euforia fora do comum."
],
"monitorizacao": [
"Litemia 5 a 7 dias após iniciar e após cada mudança de dose até estabilizar",
"Depois a cada 3 meses no primeiro ano e a cada 6 meses a partir daí (manter a cada 3 meses em idosos, em uso de medicamentos que interagem, risco renal ou tireoidiano, adesão ruim ou última litemia de 0,8 ou mais), conforme NICE CG185. Creatinina/TFG, TSH e cálcio antes de iniciar e pelo menos a cada 6 meses",
"Peso ou IMC",
"ECG basal se houver doença cardíaca ou fatores de risco. Litemia extra se surgirem sintomas de toxicidade, desidratação ou início de fármaco que interage"
],
"interacoes": [
"Aumentam a litemia e o risco de intoxicação: diuréticos tiazídicos (hidroclorotiazida, clortalidona, indapamida), IECA (enalapril, captopril), BRA (losartana, valsartana), anti-inflamatórios não esteroides (ibuprofeno, diclofenaco, naproxeno, nimesulida, cetoprofeno",
"Inclusive de venda livre), metronidazol e desidratação. Reduzem a litemia: teofilina, cafeína em excesso, acetazolamida, bicarbonato. Com ISRS, triptanos e tramadol: risco de síndrome serotoninérgica. Com antipsicóticos (especialmente haloperidol): neurotoxicidade. Dieta com muita variação de sal altera o nível"
],
"gestacao": "Se você pode engravidar, converse com o médico antes de planejar a gestação. O lítio atravessa a placenta e pode causar malformações, principalmente cardíacas, no primeiro trimestre (bula). Não pare de repente se engravidar, porque a interrupção brusca aumenta muito o risco de recaída; procure o médico logo para planejar, com ultrassom morfológico e ecocardiograma fetal e litemias frequentes, sobretudo perto do parto. A amamentação exige avaliação especializada.",
"suspensao": "Não pare de repente: a interrupção brusca aumenta o risco de recaída (mania ou depressão) e de suicídio. Se for necessário parar, o médico reduz a dose gradualmente, em geral ao longo de pelo menos 4 semanas, idealmente mais.",
"orientacoes": [
"Beba bastante água (cerca de 2 a 3 litros por dia) e mantenha o sal da comida constante, sem dietas muito restritas.",
"Não tome anti-inflamatórios (ibuprofeno, diclofenaco, nimesulida) por conta própria; para dor prefira paracetamol e avise qualquer médico que você usa lítio.",
"Colete a litemia cerca de 12 horas após a última dose, antes da dose da manhã.",
"Em caso de diarreia, vômitos ou febre, procure o médico, pois pode ser preciso ajustar a dose."
],
"alertasMedico": [
"Janela terapêutica estreita (Boxed Warning FDA). Toxicidade precipitada por tiazídicos, IECA, BRA, AINE, desidratação, dieta hipossódica e piora da função renal: evitar essas associações ou reduzir dose e dosar litemia em 5 a 7 dias. Efeitos crônicos: hipotireoidismo, hiperparatireoidismo com hipercalcemia, diabetes insipidus nefrogênico e DRC. Não renovar sem litemia, TFG, TSH e cálcio recentes (idealmente últimos 6 meses). Consta na lista C1 (entrada 103 Lítio), exigindo Receita de Controle Especial",
"Conferido na RDC 1.036/2026"
],
"fontes": [
"Bula CARBOLITIUM e CARBOLITIUM CR (Eurofarma), ANVISA. https://img.drogasil.com.br/raiadrogasil_bula/CARBOLITIUM.pdf",
"NICE CG185 (bipolar) e Quality Standard QS95, statement 5: litemia a cada 3 meses no 1o ano e depois a cada 6 meses (3/3 meses se idoso, interações, risco renal/tireoidiano, adesão ruim ou última litemia >= 0,8); TFG, função tireoidiana e cálcio pelo menos a cada 6 meses. https://www.nice.org.uk/guidance/qs95/chapter/quality-statement-5-maintaining-plasma-lithium-levels",
"ANVISA. RDC n. 1.036, de 09/07/2026 (atualiza o Anexo I da Portaria SVS/MS 344/1998; conferido o texto consolidado das listas em 24/09/2026). https://anvisalegis.datalegis.net/action/ActionDatalegis.php?acao=abrirTextoAto&tipo=RDC&numeroAto=00001036&seqAto=000&valorAno=2026&orgao=RDC%2FDC%2FANVISA%2FMS",
"Portaria SVS/MS 344/1998, texto consolidado (arts. 41, 43, 45, 46, 52, 57, 59, 60; redação dada pelas RDC 873/2024 e RDC 1.000/2025). https://anvisalegis.datalegis.net/action/ActionDatalegis.php?acao=abrirTextoAto&tipo=POR&numeroAto=00000344&seqAto=000&valorAno=1998&orgao=SVS%2FMS",
"Yatham LN et al. CANMAT/ISBD 2018 guidelines for bipolar disorder. Bipolar Disord 2018;20:97-170 (citado de memória; não reaberto nesta sessão)."
],
