"receituario": "notificacao_b",
"limiteQuantidade": "Notificação de Receita B (azul), uma substância por notificação (art. 35, §7º, Portaria SVS/MS 344/1998); até 60 dias de tratamento (art. 46), e acima disso só com justificativa com CID ou diagnóstico e posologia (art. 46, §1º). A exceção de 6 meses do art. 59 vale para a Receita de Controle Especial e não se aplica à Notificação B, mesmo em uso anticonvulsivante. Validade de 30 dias em todo o território nacional (art. 45, redação da RDC 1.000/2025, em vigor desde 13/02/2026). Talonário numerado pela vigilância sanitária; emissão eletrônica somente via SNCR, com assinatura qualificada ICP-Brasil, com liberação prevista para 30/09/2026 (RDC 1.028/2026); até lá, apenas em papel.",
