"gestacao": "Evite usar na gravidez sem orientação médica: no fim da gestação pode causar no bebê sonolência, moleza, dificuldade para respirar e sintomas de abstinência. Se planeja engravidar ou engravidou, converse com o neurologista, sem parar por conta própria; a bula brasileira desaconselha o uso durante a amamentação.",
"suspensao": "Não pare de repente nem reduza por conta própria: o corpo se acostuma com o remédio, e a interrupção brusca pode causar ansiedade, insônia, tremores e até crises convulsivas. A retirada deve ser gradual, em pequenas reduções ao longo de semanas, com orientação médica.",
