"posologiaUsual": "Ritalina: em geral 10 mg duas ou três vezes ao dia (alguns precisam de 40 a 60 mg/dia), última dose antes das 18 h. Ritalina LA: 20 mg uma vez ao dia pela manhã (pode iniciar com 10 mg). Concerta: 18 mg pela manhã em crianças e adolescentes, 18 ou 36 mg em adultos, aumentos de 18 mg por semana. Narcolepsia: apenas Ritalina de liberação imediata.",
