"Portaria SVS/MS 344/1998, texto consolidado (arts. 41, 43, 45, 46, 52, 57, 59, 60; redação dada pelas RDC 873/2024 e RDC 1.000/2025). https://anvisalegis.datalegis.net/action/ActionDatalegis.php?acao=abrirTextoAto&tipo=POR&numeroAto=00000344&seqAto=000&valorAno=1998&orgao=SVS%2FMS",
