"posologiaUsual": "Adultos: 2–3 mg/kg/dia em dose única ou dividida; avaliar o efeito após cerca de 15 dias",
"doseMaxDia": "Sem teto fixo na bula brasileira; dose guiada por resposta e nível sérico (cerca de 15–30 mcg/mL, ou 65–130 µmol/L); reduzir em idosos e em insuficiência renal ou hepática",
"portaria344": "B1 (Adendo 2: medicamentos com fenobarbital são prescritos em Receita de Controle Especial em 2 vias)",
"receituario": "controle_especial",
"limiteQuantidade": "Apesar de listado na B1, o Adendo 2 dessa lista determina prescrição em Receita de Controle Especial em 2 vias (Anexo I da Portaria 344/1998, Atualização nº 101, RDC 1.036/2026), e não em Notificação B. Validade de 30 dias em todo o território nacional (art. 52, §1º); CPF do paciente obrigatório (art. 55, b, redação da RDC 1.000/2025). Como anticonvulsivante, aplica-se na prática o limite de até 6 meses de tratamento (art. 59, parágrafo único), embora o caput do art. 59 cite nominalmente as listas C1 e C5; acima dos limites, justificar com CID ou diagnóstico e posologia (art. 60). Receita eletrônica: só por serviço de prescrição integrado ao SNCR, com assinatura eletrônica qualificada ICP-Brasil (RDC 1.000/2025; prazo de disponibilização completa do SNCR estendido para 30/09/2026 pela RDC 1.028/2026).",
