"interacoes": [
"Indutor enzimático potente: reduz a eficácia de anticoncepcionais hormonais",
"Anticoagulantes orais perdem efeito: controlar o INR com mais frequência, inclusive até 8 dias após parar o fenobarbital",
"Valproato aumenta o nível de fenobarbital (sonolência e hiperamonemia)",
"Opioides, metadona, benzodiazepínicos e álcool: risco de depressão respiratória",
"Reduz o efeito de corticoides, hormônio tireoidiano, digitoxina, quinidina e metadona",
"Contraindicado com saquinavir e com esquemas para hepatite C com sofosbuvir"
],
"gestacao": "Pela bula brasileira atual, o fenobarbital é contraindicado na gravidez e em mulheres que podem engravidar, porque aumenta o risco de malformações (cerca de 6 a 7 em cada 100) e de problemas de crescimento e de desenvolvimento do bebê. Se você pode engravidar, converse com o neurologista sobre a troca por outro remédio e, até lá, use DIU ou outro método não hormonal (a pílula perde efeito), sem parar o fenobarbital por conta própria.",
"suspensao": "Nunca pare de repente: além de fazer as crises voltarem, inclusive crises prolongadas, o corpo se acostuma com o remédio e a retirada brusca pode causar sintomas de abstinência. A redução deve ser lenta, ao longo de semanas a meses, sempre com orientação médica.",
