"gestacao": "Os estudos disponíveis não mostraram aumento claro de malformações, mas há sinais de mais bebês com baixo peso ou prematuros e risco de sintomas de abstinência no recém-nascido. Use na gravidez apenas se for realmente necessário, planeje com o médico e não pare por conta própria.",
