"monitorizacao": [
"Pele nas primeiras 8 semanas e a cada aumento de dose; confirmar que o esquema de titulação está sendo seguido",
"Não exige exames laboratoriais de rotina",
"Nível sérico e ajuste de dose ao iniciar ou suspender anticoncepcional com estrogênio, na gestação e no pós-parto, e ao associar ou retirar valproato ou indutores",
"ECG antes de iniciar se cardiopatia estrutural, arritmia, síndrome de Brugada ou uso de outros bloqueadores de sódio (atividade antiarrítmica classe IB; alerta FDA 2021)",
"Humor e ideação suicida a cada consulta"
],
"interacoes": [
"Valproato dobra o nível de lamotrigina (meia-vida de cerca de 70 h): titulação e dose pela metade; aumenta o risco de reação grave de pele",
"Carbamazepina, fenitoína, fenobarbital, primidona, rifampicina e lopinavir/ritonavir reduzem o nível de lamotrigina pela metade",
"Anticoncepcional com etinilestradiol reduz o nível de lamotrigina em cerca de 50% (pode ser preciso até dobrar a dose); o nível sobe na semana de pausa; ao suspender o estrogênio, reduzir a dose. Pílula só de progestagênio não interfere (bula FDA 04/2025)",
"Lamotrigina reduz discretamente o levonorgestrel",
"Inibe o transportador OCT2: evitar com dofetilida"
],
"gestacao": "Está entre os antiepilépticos de menor risco de malformações (cerca de 2 a 3 em cada 100). Na gestação o nível no sangue cai bastante e a dose costuma precisar de ajuste, voltando a subir depois do parto; se planeja engravidar ou engravidou, não pare o remédio, avise o neurologista e use ácido fólico conforme orientação.",
"suspensao": "Não pare por conta própria: a interrupção de repente pode trazer as crises (ou a instabilidade do humor) de volta. Se ficar vários dias seguidos sem tomar (cerca de 5 dias ou mais), não volte sozinho à dose que usava: fale com o médico, porque pode ser necessário recomeçar com dose baixa para evitar reação grave na pele.",
"orientacoes": [
"Siga à risca o esquema de aumento de dose combinado: subir mais rápido aumenta o risco de reação grave na pele",
"O comprimido dispersível pode ser engolido inteiro, mastigado ou dissolvido em um pouco de água",
"Avise o médico antes de começar ou parar pílula anticoncepcional ou qualquer outro remédio",
"Se esquecer uma dose, tome assim que lembrar; se já estiver perto do próximo horário, pule a esquecida e não tome dose dobrada"
],
"alertasMedico": [
"Rash grave (SSJ/NET): 0,08–0,3% em adultos, maioria entre 2 e 8 semanas; fatores de risco: valproato, dose inicial ou titulação acima do recomendado e HLA-B*1502 (tarja da bula FDA revisada em 10/2025; também citado na bula brasileira de 05/2026)",
"Reintrodução após mais de 5 meias-vidas sem a droga exige retitulação desde o início",
"Interações com estrogênio e com valproato: conferir contracepção e comedicações a cada renovação",
"Atividade classe IB: considerar ECG em cardiopatas e com outros bloqueadores de sódio (FDA 2021)",
"Linfo-histiocitose hemofagocítica (alerta FDA 2018): febre persistente com citopenias ou hepatite"
],
