"posologiaUsual": "Ansiedade: média de 2 a 3 mg/dia divididos em duas ou três tomadas. Insônia associada à ansiedade: 1 a 2 mg ao deitar. Idosos e debilitados: reduzir a dose inicial.",
"doseMaxDia": "10 mg/dia (faixa da bula de 1 a 10 mg/dia)",
"portaria344": "Lista B1 (psicotrópicos), Portaria SVS/MS 344/1998, conferido no Anexo I atualizado pela RDC 1.036/2026",
