"Portaria SVS/MS 344/1998, texto consolidado (arts. 41, 43, 45, 46, 52, 57, 59, 60; redação dada pelas RDC 873/2024 e RDC 1.000/2025). https://anvisalegis.datalegis.net/action/ActionDatalegis.php?acao=abrirTextoAto&tipo=POR&numeroAto=00000344&seqAto=000&valorAno=1998&orgao=SVS%2FMS",
"FDA. Boxed Warning de suicidalidade para antidepressivos (crianças, adolescentes e adultos jovens até 24 anos), presente nas bulas americanas vigentes (texto de 2007, mantido). Não reaberto nesta sessão; conteúdo de conhecimento consolidado.",
"Lam RW et al. CANMAT 2023 Update on Clinical Guidelines for Management of Major Depressive Disorder in Adults. Can J Psychiatry 2024;69(9):641-687. doi:10.1177/07067437241245384 (não reaberto nesta sessão; citado de memória, conferir)."
