"doseMaxDia": "Uso habitual até 40 mg/dia (80 mg/dia só no H. pylori); Zollinger-Ellison: início 80 mg/dia, acima disso dividir em 2 tomadas, aumentos temporários acima de 160 mg/dia. Insuficiência hepática grave: 40 mg em dias alternados.",
