"posologiaUsual": "Epilepsia: 250 mg 3–4x/dia, após titulação a partir de 100–125 mg à noite; tremor essencial: 50–250 mg/dia",
"doseMaxDia": "Epilepsia: 2.000 mg/dia; tremor essencial: 750 mg/dia (bula Primid)",
"portaria344": "C1",
"receituario": "controle_especial",
"limiteQuantidade": "Receita de Controle Especial em 2 vias, válida por 30 dias a partir da emissão em todo o território nacional (art. 52, §1º, Portaria SVS/MS 344/1998); CPF do paciente obrigatório (art. 55, b, redação da RDC 1.000/2025). Por ser anticonvulsivante, a quantidade pode chegar a até 6 meses de tratamento (art. 59, parágrafo único); no máximo 3 substâncias da lista C1 por receita (art. 57). Acima dos limites, o prescritor deve justificar com CID ou diagnóstico e posologia, datando e assinando (art. 60). Receita eletrônica: só por serviço de prescrição integrado ao SNCR, com assinatura eletrônica qualificada ICP-Brasil (RDC 1.000/2025; prazo de disponibilização completa do SNCR estendido para 30/09/2026 pela RDC 1.028/2026). O art. 59 fala em substâncias anticonvulsivantes; quando prescrito para outra indicação (tremor essencial), a aplicação dos 6 meses pode ser interpretada de forma diferente pela vigilância sanitária local: na dúvida, limitar a 60 dias (art. 59, caput) ou justificar.",
"efeitosComuns": [
"Tontura e desequilíbrio, mais fortes no início e que costumam melhorar com o tempo",
"Sonolência",
"Enjoo ou vômitos",
"Perda de apetite",
"Cansaço",
"Visão dupla"
],
"sinaisAlerta": [
"Sonolência extrema, respiração lenta ou dificuldade para acordar, principalmente se usou álcool, opioides ou calmantes",
"Manchas, bolhas ou descamação na pele",
"Palidez, fraqueza ou falta de ar fora do comum",
"Confusão mental forte",
"Tristeza profunda ou pensamentos de se machucar"
],
"monitorizacao": [
"Hemograma e bioquímica a cada 6 meses no uso prolongado (bula FDA Mysoline)",
"Nível sérico de primidona (5–12 mcg/mL) e do fenobarbital derivado quando necessário",
"Folato e vitamina D no uso prolongado (bula Primid recomenda suplementação)",
"Sedação, quedas e sinais de dependência"
],
"interacoes": [
"Indutor enzimático (como o fenobarbital): reduz a eficácia de anticoncepcionais hormonais e de varfarina",
"Valproato aumenta o fenobarbital derivado da primidona",
"Reduz o nível de lamotrigina e de outros antiepilépticos",
"Álcool, opioides e benzodiazepínicos: sedação e depressão respiratória"
],
"gestacao": "A bula recomenda evitar na gravidez. Como parte do remédio vira fenobarbital no organismo, pode ter riscos parecidos para o bebê; se você pode engravidar, use DIU ou outro método não hormonal (a pílula perde efeito) e planeje com o neurologista, sem parar por conta própria.",
"suspensao": "Não pare de repente: pode trazer as crises (ou o tremor) de volta e causar sintomas de abstinência, porque parte do remédio vira fenobarbital no organismo. A redução deve ser lenta, com orientação médica.",
"orientacoes": [
"No início, a dose é baixa e tomada à noite, subindo aos poucos; siga o esquema combinado",
"Não use bebida alcoólica nem outros calmantes sem falar com o médico",
"Tenha cuidado ao dirigir e ao levantar, principalmente nas primeiras semanas",
"Se esquecer uma dose, tome assim que lembrar; se já estiver perto do próximo horário, pule a esquecida e não tome dose dobrada"
],
"alertasMedico": [
"Metabolizada em fenobarbital: mesmos cuidados com dependência, depressão respiratória e indução enzimática",
"Tremor essencial é indicação aprovada na bula brasileira",
"Contraindicada em porfiria e em hipersensibilidade ao fenobarbital",
"Comprimidos contêm tartrazina",
"Mulher em idade fértil: bula recomenda evitar na gestação; considerar alternativa"
],
