"posologiaUsual": "50 mg uma vez ao dia, com ou sem alimento; aumentos, se necessários, a intervalos de pelo menos 7 dias. Insuficiência renal grave ou diálise: 50 mg em dias alternados.",
"doseMaxDia": "200 mg/dia (bula brasileira); doses acima de 50 mg geralmente não trazem benefício adicional",
"portaria344": "Lista C1 (outras substâncias sujeitas a controle especial), Portaria SVS/MS 344/1998, conferido no Anexo I atualizado pela RDC 1.036/2026",
"receituario": "controle_especial",
"limiteQuantidade": "Receita de Controle Especial em 2 vias: quantidade para no máximo 60 dias de tratamento (Portaria 344/98, art. 59); acima disso o prescritor precisa justificar com CID ou diagnóstico (art. 60). Validade de 30 dias a partir da emissão (art. 52, par. 1o). No máximo 3 substâncias da lista C1 por receita (art. 57).",
"efeitosComuns": [
"Enjoo, principalmente no início",
"Boca seca e suor aumentado",
"Tontura",
"Insônia ou sonolência",
"Prisão de ventre e perda de apetite",
"Diminuição do desejo sexual ou dificuldade de ejaculação"
],
"sinaisAlerta": [
"Pensamentos de se machucar ou de tirar a propria vida, ou piora brusca da tristeza, agitação ou impulsividade, principalmente nas primeiras semanas ou após mudança de dose e em pessoas com menos de 25 anos: procure ajuda imediatamente (CVV 188 ou SAMU 192).",
"Dor de cabeça forte com pressão muito alta.",
"Agitação intensa, confusão, febre, suor excessivo, tremores ou abalos musculares, diarreia forte e coração acelerado, sobretudo depois de associar outro remédio: pode ser síndrome serotoninérgica, procure emergência.",
"Euforia ou irritabilidade fora do comum, pouca necessidade de dormir, fala acelerada e gastos ou atitudes impulsivas: avise o médico logo, pode ser virada para mania.",
"Sangramentos fora do comum (nariz, gengiva, fezes escuras, manchas roxas grandes), principalmente se você usa anticoagulante, AAS ou anti-inflamatório.",
"Confusão, sonolência exagerada, dor de cabeça forte, fraqueza ou quedas, sobretudo em idosos: pode ser sódio baixo no sangue, procure atendimento."
],
"monitorizacao": [
"Pressão arterial antes de iniciar e periodicamente (aumento dose-dependente). Colesterol e triglicerídeos podem subir. Reavaliação clínica do humor e de ideação suicida nas primeiras semanas e após cada mudança de dose, sobretudo em menores de 25 anos. Sódio em idosos ou em uso de diurético se houver sintomas"
],
"interacoes": [
"Contraindicada com IMAO (esperar 7 dias após parar a desvenlafaxina e 14 dias após parar o IMAO",
"Também linezolida e azul de metileno). Risco serotoninérgico com triptanos, tramadol, outros antidepressivos, lítio e erva-de-são-joão. Risco de sangramento com AAS, anti-inflamatórios e anticoagulantes. Não associar a venlafaxina"
],
"gestacao": "Se você engravidar ou planejar engravidar, avise o médico, mas não pare o remédio por conta própria: parar de repente aumenta o risco de a depressão voltar. O médico pesa os riscos e benefícios. Uso no fim da gestação pode causar sintomas passageiros no bebê (irritabilidade, dificuldade para mamar) e raramente hipertensão pulmonar persistente no recém-nascido, por isso o parto deve ser informado à equipe. Em julho de 2025 um painel da FDA discutiu o tema, mas não houve mudança de bula até esta revisão.",
"suspensao": "Não pare de repente. A interrupção brusca pode causar tontura, sensação de choque, enjoo, irritabilidade, insônia, sonhos vívidos e sintomas parecidos com gripe (síndrome de descontinuação). Quando for a hora de parar, o médico reduz a dose aos poucos, em geral ao longo de semanas ou meses, e mais devagar se surgirem sintomas.",
"orientacoes": [
"Engula o comprimido inteiro; pode aparecer nas fezes a 'casca' vazia, isso é normal.",
"Meça a pressão de vez em quando.",
"O efeito completo costuma aparecer entre 2 e 6 semanas.",
"Evite álcool."
],
"alertasMedico": [
"Elevação de PA dose-dependente: controlar HAS antes. Ajuste renal (ClCr < 30: 50 mg em dias alternados",
"ClCr 30-50: máximo 50 mg/dia). Descontinuação intensa. Boxed Warning de suicidalidade até 24 anos. Receita C1"
],
