"posologiaUsual": "Epilepsia: 100–400 mg/dia em 2 tomadas; enxaqueca: 50–100 mg/dia em 2 tomadas; titulação de 25 mg por semana",
"doseMaxDia": "Epilepsia: 500 mg/dia em monoterapia na bula brasileira (FDA: 400 mg/dia); enxaqueca: 200 mg/dia; reduzir se ClCr < 70 mL/min",
"portaria344": "C1",
"receituario": "controle_especial",
"limiteQuantidade": "Receita de Controle Especial em 2 vias, válida por 30 dias a partir da emissão em todo o território nacional (art. 52, §1º, Portaria SVS/MS 344/1998); CPF do paciente obrigatório (art. 55, b, redação da RDC 1.000/2025). Por ser anticonvulsivante, a quantidade pode chegar a até 6 meses de tratamento (art. 59, parágrafo único); no máximo 3 substâncias da lista C1 por receita (art. 57). Acima dos limites, o prescritor deve justificar com CID ou diagnóstico e posologia, datando e assinando (art. 60). Receita eletrônica: só por serviço de prescrição integrado ao SNCR, com assinatura eletrônica qualificada ICP-Brasil (RDC 1.000/2025; prazo de disponibilização completa do SNCR estendido para 30/09/2026 pela RDC 1.028/2026). O art. 59 fala em substâncias anticonvulsivantes; quando prescrito para outra indicação (profilaxia de enxaqueca), a aplicação dos 6 meses pode ser interpretada de forma diferente pela vigilância sanitária local: na dúvida, limitar a 60 dias (art. 59, caput) ou justificar.",
"efeitosComuns": [
"Formigamento nas mãos, nos pés ou no rosto",
"Perda de apetite e de peso",
"Dificuldade para encontrar palavras, lentidão para pensar ou falhas de memória",
"Sonolência, cansaço ou tontura",
"Mudança no gosto, principalmente de bebidas com gás",
"Nervosismo"
],
"sinaisAlerta": [
"Visão embaçada de repente, dor nos olhos ou olho vermelho, principalmente no primeiro mês: procure atendimento urgente",
"Dor forte nas costas ou na lateral da barriga, ou sangue na urina",
"Febre ou calor excessivo com pouco ou nenhum suor",
"Respiração rápida, cansaço extremo ou confusão",
"Manchas, bolhas ou descamação na pele",
"Tristeza profunda ou pensamentos de se machucar"
],
"monitorizacao": [
"Bicarbonato sérico no início e periodicamente (acidose metabólica)",
"Creatinina/ClCr para ajuste de dose; perguntar sobre história de cálculo renal",
"Sintomas visuais, principalmente no primeiro mês (miopia aguda e glaucoma de ângulo fechado)",
"Peso e queixas cognitivas a cada consulta",
"Amônia se confusão ou letargia, sobretudo em uso com valproato",
"Mulher com potencial de engravidar: teste de gravidez antes de iniciar e contracepção altamente eficaz"
],
"interacoes": [
"Anticoncepcional com estrogênio: exposição ao etinilestradiol cai 18–30% com 200–800 mg/dia (bula brasileira); FDA alerta perda de eficácia e sangramento de escape, sobretudo acima de 200 mg/dia",
"Fenitoína e carbamazepina reduzem o nível de topiramato",
"Valproato: hiperamonemia e hipotermia",
"Acetazolamida e dieta cetogênica: mais risco de cálculo renal e acidose",
"Lítio: monitorar nível com doses altas de topiramato",
"Álcool e depressores do sistema nervoso central somam sonolência"
],
"gestacao": "Aumenta o risco de malformações, como fenda no lábio ou no céu da boca, e há estudos sugerindo mais risco de alterações do desenvolvimento, como autismo; pela bula brasileira, é contraindicado na gravidez para prevenção de enxaqueca, e mulheres que podem engravidar só devem usá-lo com teste de gravidez antes de começar e método anticoncepcional altamente eficaz. Em doses altas a pílula pode perder efeito, então planeje qualquer gravidez com o neurologista e não pare o remédio por conta própria.",
"suspensao": "Não pare de tomar nem diminua a dose por conta própria, mesmo que esteja há muito tempo sem crises. Parar de repente pode fazer as crises voltarem, às vezes mais fortes ou prolongadas. Se for o caso de retirar ou trocar o remédio, o médico fará a redução aos poucos, ao longo de semanas.",
"orientacoes": [
"Beba bastante água ao longo do dia para ajudar a prevenir pedras nos rins",
"Tome o comprimido com bastante água, sem partir, triturar ou mastigar; pode ser junto das refeições",
"Em dias muito quentes ou com exercício intenso, hidrate-se bem e evite calor excessivo",
"Se esquecer uma dose, tome assim que lembrar; se já estiver perto do próximo horário, pule a esquecida e não tome dose dobrada"
],
