"Miopia aguda com glaucoma secundário de ângulo fechado, em geral no primeiro mês",
"Acidose metabólica, nefrolitíase e oligoidrose",
"Efeitos cognitivos e de linguagem (28% com 200 mg/dia na enxaqueca)",
"Topamax: a fabricante (J&J) comunicou à ANVISA em 06/2026 a descontinuação definitiva no Brasil, sem motivo de segurança; orientar troca por genérico ou similar"
